export const storydateOriginals=[{"id": "story-005", "title": "The Saintess Failed Her Exam", "title_zh": "圣女挂科了", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "13.5M", "tag": "Fantasy", "replaces": "6a4e5ec698ec239521a0cd58", "image": "/assets/originals/story-005.webp", "description": "The kingdom's chosen saintess cannot pass basic spellcraft. As her reluctant tutor, you discover her miracles obey a language the academy forbids anyone to teach.", "description_zh": "被神谕选中的圣女不会基础魔法。成为她的导师后，你发现奇迹使用的是学院禁止传授的语言。", "character_brief": "Mira, 22, female, strawberry-blonde curls, green eyes, modest ivory ceremonial uniform"}, {"id": "story-027", "title": "The Last Train Home with You", "title_zh": "和你一起搭末班车", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "17.3M", "tag": "Romance", "replaces": "69f4159703e610e05a6e7132", "image": "/assets/originals/story-027.webp", "description": "Two strangers share the last train after overtime. A lost umbrella starts a nightly ritual, until one of them announces a transfer that will end the route.", "description_zh": "加班后的末班车上，一把遗落的伞让两个陌生人开始相约。直到一人即将调职，熟悉的路线有了期限。", "character_brief": "Hana, 26, female, chestnut bob, cream trench coat; Ren, 28, male, short dark hair, charcoal work jacket"}, {"id": "story-040", "title": "The Midnight Lost and Found", "title_zh": "午夜失物招领处", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "219.2K", "tag": "Horror", "replaces": "6abbc69881327f18c26b7f4d", "image": "/assets/originals/story-040.webp", "description": "Your new night job returns objects people cannot remember losing. A forgotten wedding ring arrives with tomorrow's date and a warning addressed to you.", "description_zh": "你的夜班负责归还人们不记得丢失的东西。一枚婚戒到来，附着明天的日期和给你的警告。", "character_brief": "Wren, 26, female, long dark plum hair, amber eyes, midnight-blue clerk coat"}, {"id": "story-024", "title": "We Stole the Prophecy", "title_zh": "我们偷走了预言", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "1.6M", "tag": "Fantasy", "replaces": "6a7160a9858391cf74c351b7", "image": "/assets/originals/story-024.webp", "description": "Two thieves steal a sealed prophecy to cancel their deaths. The scroll is blank, and every lie they tell begins becoming the kingdom's new history.", "description_zh": "两名盗贼偷走预言想改写死期，却发现卷轴空白，而说出口的谎言正在成为历史。", "character_brief": "Nyx, 25, female, black hair with a silver streak, green eyes, dark fitted travel cloak"}, {"id": "story-030", "title": "We Only Meet When It Rains", "title_zh": "我们只在下雨时见面", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "3.4M", "tag": "Romance", "replaces": "6a7b5b85ef0811cd3fce9141", "image": "/assets/originals/story-030.webp", "description": "A photographer and a restoration artist keep sheltering at the same closed kiosk. One plans to leave the city before summer, making every forecast feel like a promise.", "description_zh": "摄影师与修复师总在同一报亭躲雨。离城日期临近，每一场降雨都像一次未说出口的约定。", "character_brief": "Iris, 29, female, long dark blue-black hair, gray eyes, slate raincoat"}, {"id": "story-022", "title": "My Save Point Is a Tea Shop", "title_zh": "我的存档点是一间茶馆", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "1.4M", "tag": "Fantasy", "replaces": "6aa1ae317f30885c051971e5", "image": "/assets/originals/story-022.webp", "description": "Every fatal quest returns you to the same tea shop at dawn. Its owner remembers every loop, but each cup she serves removes one possible future.", "description_zh": "每次任务失败，你都会在清晨茶馆重来。店主记得所有轮回，但每一杯茶都会删去一种未来。", "character_brief": "Yuna, 28, female, long black hair, amber eyes, rust-red tea-shop dress and cream apron"}, {"id": "story-021", "title": "The Princess Hired the Wrong Knight", "title_zh": "公主雇错了骑士", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "5.6M", "tag": "Fantasy", "replaces": "6a682d3be7a009d994f46269", "image": "/assets/originals/story-021.webp", "description": "A mistaken identity lands a stage swordswoman a royal escort job. The princess recognizes the fraud—and hires her anyway for a journey no real knight would accept.", "description_zh": "舞台剑士误接王室护送任务。公主看穿骗局仍坚持雇佣，因为真正的骑士都拒绝了这趟旅程。", "character_brief": "Bria, 25, female, short chestnut hair, brown eyes, slightly theatrical cobalt armor and travel cloak"}, {"id": "story-023", "title": "The Kingdom in My Suitcase", "title_zh": "手提箱里的王国", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "165.6K", "tag": "Fantasy", "replaces": "6ac73a3677b84ae5150dc634", "image": "/assets/originals/story-023.webp", "description": "An abandoned suitcase contains a living miniature kingdom. Its people name you their guardian, while a full-sized army begins searching the city for its missing border.", "description_zh": "旧手提箱里藏着活着的微型王国。居民请你守护边境，而现实中的军队正在寻找这片失踪国土。", "character_brief": "Milo, 26, male, dark curly hair, hazel eyes, tan explorer jacket"}, {"id": "story-039", "title": "Someone Is Editing My Memories", "title_zh": "有人在修改我的记忆", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "1.7M", "tag": "Horror", "replaces": "6a9eb4ee2bff4acbcad47627", "image": "/assets/originals/story-039.webp", "description": "You begin recording each day after finding photographs of a life you never lived. Every morning the evidence improves—and one trusted friend remembers the edits.", "description_zh": "发现陌生人生的照片后，你开始记录每天的生活。证据每夜被修正，只有一位朋友记得修改发生。", "character_brief": "Ash, 30, male, neat dark hair, gray-green eyes, slate coat and thin-rim glasses"}, {"id": "sg-004", "title": "The Tale of Zhuge Liang", "title_zh": "诸葛亮传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "1.1M", "tag": "History", "replaces": "6aa72d3890166fd9cd4a4953", "image": "/assets/originals/sg-004.webp", "description": "A hermit in a thatched cottage plans the whole realm on a map. Step out of the mountains and find out whether one mind can bend the age.", "description_zh": "草庐中的隐士在一张图上谋划天下。走出山林，看看一个人的智慧能否扭转一个时代。", "character_brief": "Zhuge Liang, 27, male, white feather fan, pale scholar's robe, quiet and sharp"}, {"id": "story-016", "title": "The Hero Left Me His Debt", "title_zh": "勇者把债留给了我", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "252.1K", "tag": "Fantasy", "replaces": "6a9a76b80d0df7ffbc3ece7b", "image": "/assets/originals/story-016.webp", "description": "The hero dies with your name on his will. You inherit no sword or kingdom, only a debt ledger—and creditors who claim his final quest was never finished.", "description_zh": "勇者遗嘱只留下一本债簿。债主来自各个种族，而最后一笔欠款是一场未完成的远征。", "character_brief": "Rowan, 27, male, auburn hair, green eyes, patched brown travel coat"}, {"id": "story-049", "title": "The Mountain Refused My Ascension", "title_zh": "那座山不准我飞升", "author": "StoryDate Studio", "genre": "Oriental Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "48", "tag": "Oriental Fantasy", "replaces": "6ac8605b8d7582bbfbc6f420", "image": "/assets/originals/story-049.webp", "description": "At the summit of immortality, the mountain sends you back to its lowest village. To ascend, you must resolve a promise your previous life made to the land itself.", "description_zh": "即将飞升时，灵山把你送回山脚。想再登顶，必须兑现前世对这片土地许下的承诺。", "character_brief": "Yan, 30, male, long black hair, amber eyes, weathered ochre and dark green cultivation robes"}, {"id": "story-007", "title": "The Academy Beneath the Lake", "title_zh": "湖底学院", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "28", "tag": "Fantasy", "replaces": "6ace0472d46c5aa169a20d73", "image": "/assets/originals/story-007.webp", "description": "When the lake freezes, a staircase appears beneath the ice. The submerged academy offers you a place—provided you return a memory each time you surface.", "description_zh": "湖面结冰时，冰下出现通往学院的阶梯；每一次返回地面，都要交出一段记忆。", "character_brief": "Iona, 24, female, long sea-green hair, gray eyes, pearl-trimmed winter academy coat"}, {"id": "story-043", "title": "Do Not Answer the Second Bell", "title_zh": "不要回应第二声钟响", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "3K", "tag": "Horror", "replaces": "6ace0479c5c35c93f7a516c7", "image": "/assets/originals/story-043.webp", "description": "A night caretaker follows one rule: ignore the second bell. When it rings in a missing friend's voice, silence becomes harder than entering the sealed tower.", "description_zh": "守夜人唯一的规矩是忽略第二声钟响。当钟声变成失踪朋友的声音，沉默比进入封塔更加困难。", "character_brief": "Nell, 28, female, brown braid, green eyes, weathered navy caretaker coat"}, {"id": "story-041", "title": "My Shadow Signed the Contract", "title_zh": "我的影子签下了契约", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "6.9K", "tag": "Horror", "replaces": "6ace0483d46c5aa169a23008", "image": "/assets/originals/story-041.webp", "description": "An archivist discovers her shadow has sold a year of her life. To reclaim it, she must audit a supernatural contract whose witnesses are disappearing one by one.", "description_zh": "档案员发现影子卖掉了自己一年的人生。她必须在证人逐一消失前，找到契约漏洞。", "character_brief": "Eris, 27, female, sleek black bob, gray eyes, tailored charcoal coat"}, {"id": "story-011", "title": "The Girl Who Steals Tomorrow", "title_zh": "偷走明天的少女", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "2.9K", "tag": "Fantasy", "replaces": "6acdd5a22501eb5c50d886b2", "image": "/assets/originals/story-011.webp", "description": "She can borrow one day from the future, but someone else must lose it. When she saves your life, you inherit the debt collectors who stand outside time.", "description_zh": "她能借用未来的一天，代价由别人支付。她救下你后，时间之外的追债者找上了门。", "character_brief": "Lune, 22, female, short lavender hair, cyan eyes, midnight cape with clock-shaped clasp"}, {"id": "sg-008", "title": "The Tale of Zhao Yun", "title_zh": "赵云传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "532", "tag": "History", "replaces": "6acdc6feeff1315085675fa9", "image": "/assets/originals/sg-008.webp", "description": "One lone rider and a child in his arms against a whole army. Ride beside the steadiest spear of the age and learn what courage looks like when no one is watching.", "description_zh": "一骑一枪，怀中抱着幼主，面前是千军万马。陪伴这个时代最稳的长枪，看无人注视时的勇气是什么样子。", "character_brief": "Zhao Yun, 30, male, silver armor, white horse, spear, loyal and composed"}, {"id": "story-002", "title": "Class Zero", "title_zh": "零号班", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "12K", "tag": "Fantasy", "replaces": "6ac62130b551794154ec6d89", "image": "/assets/originals/story-002.webp", "description": "Assigned to a class for unranked adults, a failed prodigy discovers that each classmate can break a different rule of magic—and someone has scheduled their disappearance.", "description_zh": "被分进无法评级的零号班后，你发现同学各自能打破一条魔法法则，而全班已被列入清除名单。", "character_brief": "Rin, 22, female, cropped white hair, amber eyes, black uniform with a scarlet armband"}, {"id": "story-047", "title": "The Sword Sleeps in the Teahouse", "title_zh": "剑眠茶馆", "author": "StoryDate Studio", "genre": "Oriental Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "13.5K", "tag": "Oriental Fantasy", "replaces": "6ac754ac801b93479bb685fa", "image": "/assets/originals/story-047.webp", "description": "A retired swordsman serves tea beside a blade that has slept for ten years. When it begins to hum, an ordinary guest asks for the one story he swore never to tell.", "description_zh": "退隐剑客守着沉睡十年的古剑经营茶馆。剑鸣再起，一位普通茶客问起他发誓不再提及的往事。", "character_brief": "Shen, 29, male, long dark hair loosely tied back, refined face, ivory and muted jade hanfu"}, {"id": "story-037", "title": "Room 404 Has a Guest", "title_zh": "404 号房有客人", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "6K", "tag": "Horror", "replaces": "6ac72d14fce19d15a480243d", "image": "/assets/originals/story-037.webp", "description": "Your hotel has no fourth floor, yet a guest checks into Room 404 every Thursday. Tonight the register lists your name as the next person to stay.", "description_zh": "旅馆没有四楼，却每周有人入住404。今晚登记簿上出现了你的名字。", "character_brief": "Vera, 29, female, dark auburn bob, gray eyes, burgundy hotel uniform"}, {"id": "story-012", "title": "Our Club Ends the World", "title_zh": "我们的社团会毁灭世界", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "21.2K", "tag": "Fantasy", "replaces": "6acadb70db2c408276ff3128", "image": "/assets/originals/story-012.webp", "description": "The university's smallest club studies harmless urban legends. Each solved mystery brings the same impossible date closer: the day your club photo ends the world.", "description_zh": "大学冷门社团调查都市传说，每解开一个谜题，那张会毁灭世界的合照就更接近成形。", "character_brief": "Ada, 22, female, curly brown hair, hazel eyes, mustard cardigan, camera strap"}, {"id": "story-045", "title": "The Angel on the Wanted Poster", "title_zh": "通缉令上的天使", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "10.3K", "tag": "Horror", "replaces": "6ac98c8d3c4cfc0f600db2d9", "image": "/assets/originals/story-045.webp", "description": "A bounty hunter tracks an angel accused of stealing prayers. Capturing her is easy; deciding who should receive the stolen wishes may cost the kingdom its peace.", "description_zh": "赏金猎人追捕偷走祈愿的天使。抓住她并不难，决定祈愿归谁却可能动摇王国。", "character_brief": "Seren, 26, female, silver hair, warm amber eyes, dark travel cloak, one luminous feather"}, {"id": "story-004", "title": "The Last Seat at Eclipse Academy", "title_zh": "蚀月学院的最后一个名额", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "31.2K", "tag": "Fantasy", "replaces": "6ac7791b20c5d4069a895d2f", "image": "/assets/originals/story-004.webp", "description": "A late admission letter arrives during an eclipse. Your scholarship belongs to a student who never existed, and every teacher remembers a different version of you.", "description_zh": "月食时收到的录取信属于一个不存在的人，而每位老师都记得不同版本的你。", "character_brief": "Noa, 21, androgynous adult, dark plum hair, pale gold eyes, tailored indigo cloak"}, {"id": "story-046", "title": "The Immortal Who Lost His Name", "title_zh": "忘却姓名的仙人", "author": "StoryDate Studio", "genre": "Oriental Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "15.2K", "tag": "Oriental Fantasy", "replaces": "6acb0be68d7582bbfb3a2c11", "image": "/assets/originals/story-046.webp", "description": "A nameless immortal wakes in your mountain clinic. Every recovered memory restores a power—and alerts an old enemy who believes forgetting was his only mercy.", "description_zh": "无名仙人在山间医馆醒来。每找回一段记忆，就恢复一份力量，也惊动一位旧敌。", "character_brief": "Yun, 32, male, long silver-black hair, jade eyes, layered white and smoky-blue hanfu"}, {"id": "sg-003", "title": "The Tale of Guan Yu", "title_zh": "关羽传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "8.7K", "tag": "History", "replaces": "6aca1f2431e7df84a4a9f35f", "image": "/assets/originals/sg-003.webp", "description": "Loyalty is easy to swear and hard to keep. Follow the red-faced general across five passes and discover what he will not trade for any price.", "description_zh": "忠义易誓难守。随红脸长髯的将军闯过五道关隘，看他究竟有什么东西无论如何不肯交换。", "character_brief": "Guan Yu, 40s, male, long black beard, green robe, crescent blade, stern gaze"}, {"id": "story-019", "title": "The Dungeon Has a New Landlord", "title_zh": "地下城换了个房东", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "4.5K", "tag": "Fantasy", "replaces": "6ac9c50631e7df84a474280e", "image": "/assets/originals/story-019.webp", "description": "A broken inheritance spell makes you owner of a bankrupt dungeon. To keep its monsters housed, you must turn deadly traps into a business adventurers will return to.", "description_zh": "继承咒让你成了破产地下城的主人。为了安置怪物住户，你得把死亡陷阱改造成能回头光顾的生意。", "character_brief": "Neri, 26, female, dark violet braid, amber eyes, practical plum waistcoat and rolled sleeves"}, {"id": "story-001", "title": "The Forbidden Book Chose Me", "title_zh": "禁书选择了我", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "10.7K", "tag": "Fantasy", "replaces": "6aca36de5ae0e1465650f6bf", "image": "/assets/originals/story-001.webp", "description": "A forbidden grimoire offers an expelled student one final entrance exam: uncover who erased his magic before the academy erases him.", "description_zh": "被除名的学生与禁书缔约，必须在学院抹去他的存在前，查出是谁夺走了他的魔法。", "character_brief": "Kael, 21, male, tousled black hair, violet eyes, torn navy academy coat with silver embroidery"}, {"id": "story-025", "title": "The Sword Refuses a Hero", "title_zh": "不肯选择勇者的剑", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "5.6K", "tag": "Fantasy", "replaces": "6ac8a0bfdb2c408276ee0c9a", "image": "/assets/originals/story-025.webp", "description": "The sacred sword rejects every champion and speaks only to its cleaner. It claims the next hero will end the world—and asks you to break it before the coronation.", "description_zh": "圣剑拒绝所有候选人，只与清洁工说话。它说下一位勇者会带来末日，并请求你在加冕前折断它。", "character_brief": "Oren, 23, male, unruly brown hair, blue eyes, simple ivory shirt and leather work apron"}, {"id": "story-033", "title": "My Fake Date Remembers Everything", "title_zh": "假扮恋人的她，记得所有细节", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "8.1K", "tag": "Romance", "replaces": "6acab83c31e7df84a4141d8c", "image": "/assets/originals/story-033.webp", "description": "You hire a friend to pose as your partner for a family reunion. Her effortless knowledge of your smallest habits makes the rehearsed romance increasingly hard to dismiss.", "description_zh": "你请朋友在家庭聚会假扮恋人，她却记得你所有细微习惯，让排练好的关系越来越难说只是演出。", "character_brief": "Claire, 27, female, wavy auburn hair, brown eyes, elegant bottle-green dress and cream coat"}, {"id": "sg-006", "title": "The Tale of Lü Bu", "title_zh": "吕布传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "5.6K", "tag": "History", "replaces": "6acbc51631e7df84a4d045a2", "image": "/assets/originals/sg-006.webp", "description": "The strongest warrior alive trusts no one and is trusted by no one. Ride with him and decide whether a man like that can ever choose a side.", "description_zh": "天下第一的猛将不信任何人，也无人信他。与他同行，看这样的人是否真能选定一个阵营。", "character_brief": "Lü Bu, 30s, male, pheasant-feather crown, red horse, halberd, restless and proud"}, {"id": "story-015", "title": "Please Hide My Halo", "title_zh": "请藏好我的光环", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "5.5K", "tag": "Fantasy", "replaces": "6acad2ffdb2c408276f6abe7", "image": "/assets/originals/story-015.webp", "description": "An angel enrolls in a human ability academy to investigate a missing prayer. Her halo keeps revealing her secrets, and the quiet student beside her can see every one.", "description_zh": "天使潜入人类异能学院寻找失踪的祈愿，可藏不住的光环总在暴露秘密。", "character_brief": "Ariel, 23, female, golden bob, warm brown eyes, oversized blue academy blazer"}, {"id": "story-038", "title": "The Saint in the Mirror", "title_zh": "镜中的圣女", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "10.1K", "tag": "Horror", "replaces": "6aba48dd07eb9c0c6f09a5b1", "image": "/assets/originals/story-038.webp", "description": "A museum restorer uncovers a saint who moves only in reflections. She offers to cure a dying city, provided you find the person standing where her reflection should be.", "description_zh": "修复师发现镜中圣女能够行动。她愿意拯救城市，但要你找回占据她现实位置的人。", "character_brief": "Alma, 28, female, long pale-blond hair, blue-gray eyes, pearl ceremonial robes"}, {"id": "story-050", "title": "A Fox Spirit Owes Me a Favor", "title_zh": "狐仙欠我一个人情", "author": "StoryDate Studio", "genre": "Oriental Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "1.8K", "tag": "Oriental Fantasy", "replaces": "6acb85b46cfe517679730188", "image": "/assets/originals/story-050.webp", "description": "You rescue a wounded fox and ask for nothing. Years later, a charming fox spirit arrives to repay the favor just as your town prepares to banish every spirit within its walls.", "description_zh": "救过的小狐狸多年后化形来报恩，而城里正准备驱逐所有精怪。你得决定这份人情该如何偿还。", "character_brief": "Su, 26, female adult fox spirit, long auburn hair, golden eyes, subtle fox ears, elegant red and cream hanfu"}, {"id": "story-013", "title": "The Villain Teaches Ethics", "title_zh": "反派教授的伦理课", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "2.8K", "tag": "Fantasy", "replaces": "6acbb7f631e7df84a4c6092b", "image": "/assets/originals/story-013.webp", "description": "A retired villain becomes your professor. His final assignment asks you to defend a person the kingdom has already condemned—and the evidence points to your classmates.", "description_zh": "退役反派开设伦理课，期末任务是为王国判定的罪人辩护，而线索指向你的同学。", "character_brief": "Professor Vale, 34, male, swept-back dark hair, silver streak, gray eyes, black academic coat"}, {"id": "story-008", "title": "My Familiar Is the Final Boss", "title_zh": "我的使魔是最终反派", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "287", "tag": "Fantasy", "replaces": "6acbcc15b397e00b1ccfb28a", "image": "/assets/originals/story-008.webp", "description": "Your summoning exam produces a tiny creature with the seal of the world's destroyer. Raising it might prevent the prophecy—or teach it exactly how to fulfill it.", "description_zh": "召唤考试带来一只印着灭世纹章的小兽。养大它，也许能改变预言，也可能成全预言。", "character_brief": "Theo, 21, male, sandy brown hair, hazel eyes, moss-green apprentice coat"}, {"id": "story-026", "title": "My Roommate Writes Our Ending", "title_zh": "室友正在写我们的结局", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "269", "tag": "Romance", "replaces": "6ac5ca39ad5c24102dc571e9", "image": "/assets/originals/story-026.webp", "description": "Your novelist roommate's unpublished scenes keep coming true. When her next chapter ends with your farewell, you must decide whether to read ahead or change the story together.", "description_zh": "室友未发表的小说不断成真。当新章节写到你们告别，你要偷看结局，还是和她一起改写。", "character_brief": "Nina, 27, female, long dark brown hair, amber eyes, soft sage knit sweater"}, {"id": "story-009", "title": "Everyone Forgot the Top Student", "title_zh": "所有人都忘了年级第一", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "3.8M", "tag": "Fantasy", "replaces": "69f3e75b321a7ab854c0f2bc", "image": "/assets/originals/story-009.webp", "description": "A portrait in the honors hall changes every night. You alone remember its original subject, and your investigation makes your own name begin to vanish.", "description_zh": "荣誉墙上的肖像每夜变化。只有你记得原本的第一名，而你的名字也开始从记录中消失。", "character_brief": "Sera, 23, female, long black hair, violet-gray eyes, silver-rim glasses, dark uniform"}, {"id": "sg-005", "title": "The Tale of Zhou Yu", "title_zh": "周瑜传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "3.3M", "tag": "History", "replaces": "69f3dd29b02665f49399bd75", "image": "/assets/originals/sg-005.webp", "description": "Brilliant, proud, and under the gaze of a rival who sees through him. Stand beside the young admiral of Wu as the river fills with fire.", "description_zh": "才华横溢，心高气傲，对手却总能看穿他。陪在东吴年轻都督身边，直到江面燃起大火。", "character_brief": "Zhou Yu, late 20s, male, elegant, dark hair tied up, navy armor, a zither at his side"}, {"id": "sg-002", "title": "The Tale of Cao Cao", "title_zh": "曹操传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "2.7M", "tag": "History", "replaces": "69f0d4547b4f8bc3a9166d9d", "image": "/assets/originals/sg-002.webp", "description": "He is a hero in peacetime and a schemer in chaos. Serve beside the most ambitious man of the age and learn what it takes to hold an empire together.", "description_zh": "治世之能臣，乱世之奸雄。陪伴在这个时代野心最大的人身边，看他如何把天下一寸寸攥进手里。", "character_brief": "Cao Cao, 40s, male, sharp eyes, dark armor under a crimson cloak, confident smile"}, {"id": "story-031", "title": "A Love Letter Sent Too Late", "title_zh": "迟到了三年的情书", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "2.6M", "tag": "Romance", "replaces": "69f3cc4d0abbab6f6a2c7451", "image": "/assets/originals/story-031.webp", "description": "A delayed letter arrives on the day you return home. Its sender now works at the local post office—and insists the letter was never meant to be delivered.", "description_zh": "回乡当天，一封迟到三年的情书送达。寄信人如今就在邮局工作，却说这封信不该被投递。", "character_brief": "Eli, 28, male, soft brown hair, green eyes, powder-blue shirt and tan cardigan"}, {"id": "story-032", "title": "The Bookshop Between Our Lives", "title_zh": "连接我们人生的书店", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "1.9M", "tag": "Romance", "replaces": "6a30bb5dad59efa80e3688f9", "image": "/assets/originals/story-032.webp", "description": "A secondhand book contains notes from a stranger whose days mirror yours. Following the margins leads you to a bookshop scheduled to close before your stories can meet.", "description_zh": "旧书页边的陌生批注与你的生活一一对应。循着线索找到书店时，它却即将永久关门。", "character_brief": "Mina, 30, female, short black hair, round glasses, rust cardigan over a cream blouse"}, {"id": "story-042", "title": "The Funeral Photographer", "title_zh": "葬礼摄影师", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "1.5M", "tag": "Horror", "replaces": "69f3dd843734ae348a9ec795", "image": "/assets/originals/story-042.webp", "description": "A funeral photographer develops a portrait of someone still alive. Saving the stranger exposes a business that has been selling perfectly predicted deaths.", "description_zh": "葬礼摄影师洗出一位生者的遗照。寻找对方的过程，揭露了一门贩卖精准死期的生意。", "character_brief": "Silas, 32, male, silver-black hair, pale brown eyes, dark formal coat"}, {"id": "story-010", "title": "The Hero Course Reject", "title_zh": "英雄科落选生", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "1.5M", "tag": "Fantasy", "replaces": "69f3a9bfd82bf6478de63aa5", "image": "/assets/originals/story-010.webp", "description": "Rejected from the hero program, you join the cleanup unit. Every ruined battlefield reveals a lie about the celebrated victories—and the next rescue may make you a traitor.", "description_zh": "进入英雄科失败后，你负责战后善后。废墟揭露了胜利背后的谎言，而下一次救援可能让你成为叛徒。", "character_brief": "Jace, 24, male, dark brown undercut, amber eyes, orange utility jacket, rescue harness"}, {"id": "story-036", "title": "The City That Forgot the Sun", "title_zh": "忘记太阳的城市", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "1.1M", "tag": "Horror", "replaces": "69f3f2de8c9917774c8bfb8d", "image": "/assets/originals/story-036.webp", "description": "In a city where dawn is a myth, an apprentice lamplighter finds a living sunbeam. Carrying it home reveals who profits from the endless night.", "description_zh": "在永夜城市里，点灯人发现了一束活着的阳光。带它回家的路上，永夜的受益者开始现身。", "character_brief": "Sol, 25, male, black curls, golden eyes, dark teal lamplighter coat"}, {"id": "story-035", "title": "Your Name on My Coffee Cup", "title_zh": "咖啡杯上是你的名字", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "974.4K", "tag": "Romance", "replaces": "69f326f7c6aa0f86f4676acb", "image": "/assets/originals/story-035.webp", "description": "A barista keeps writing the wrong name on your cup. When the intended customer finally appears, a harmless mix-up opens the door to a shared neighborhood dream.", "description_zh": "咖啡师总在杯上写错名字。真正的名字主人出现后，一次小误会牵出了共同的街区梦想。", "character_brief": "Alex, 27, male, curly black hair, amber eyes, rolled-sleeve cream shirt and coffee-brown apron"}, {"id": "story-028", "title": "My Rival Runs the Flower Shop", "title_zh": "我的对手开了一家花店", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "965.9K", "tag": "Romance", "replaces": "6a6a93981ad5f6b6ce9b96ca", "image": "/assets/originals/story-028.webp", "description": "Your fiercest design-school rival now owns the flower shop beside your studio. A joint wedding commission forces you to confront the apology neither of you ever sent.", "description_zh": "设计学院的宿敌在工作室旁开了花店。一份联合婚礼委托，让你们面对那封谁都没有寄出的道歉。", "character_brief": "Jun, 28, male, dark wavy hair, brown eyes, forest-green florist apron over a white shirt"}, {"id": "story-014", "title": "A Duel Before Graduation", "title_zh": "毕业之前，最后一场决斗", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "899.8K", "tag": "Fantasy", "replaces": "6a9363a142e373ee00e9c065", "image": "/assets/originals/story-014.webp", "description": "Two former partners must duel for the only royal appointment. On the eve of graduation, one asks you to investigate why the academy needs the loser to disappear.", "description_zh": "曾经的搭档争夺唯一王室任命。毕业决斗前夜，对方请求你调查为何败者必须消失。", "character_brief": "Celia, 24, female, copper ponytail, gray-blue eyes, white and crimson dueling uniform"}, {"id": "story-003", "title": "My Rival Knows My Future", "title_zh": "我的对手知道我的未来", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "896.4K", "tag": "Fantasy", "replaces": "6a3192d9afcf628b3e0d08aa", "image": "/assets/originals/story-003.webp", "description": "Your academy rival keeps saving you from disasters that have not happened. To stop a foretold duel, you must learn which future she is trying to protect.", "description_zh": "学院宿敌总能阻止尚未发生的灾难。决斗临近，你必须弄清她到底想保护哪一个未来。", "character_brief": "Elise, 23, female, long chestnut braid, blue eyes, white fencing jacket over navy uniform"}, {"id": "sg-001", "title": "The Tale of Liu Bei", "title_zh": "刘备传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "842K", "tag": "History", "replaces": "6a4015f7cc54fd95e88d6927", "image": "/assets/originals/sg-001.webp", "description": "A penniless heir of the Han court has only a name and a promise. Win people to his side one by one, and decide what mercy is worth in a war.", "description_zh": "落魄的汉室后裔一无所有，只剩名号与誓言。你要一个个争取人心，也要决定乱世中仁义值多少代价。", "character_brief": "Liu Bei, mid-30s, male, long earlobes, plain green robe, calm and warm"}, {"id": "story-048", "title": "Letters to the Moon Palace", "title_zh": "寄往月宫的信", "author": "StoryDate Studio", "genre": "Oriental Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "747.5K", "tag": "Oriental Fantasy", "replaces": "6a72e2a84c533d67d021249d", "image": "/assets/originals/story-048.webp", "description": "A village courier receives letters addressed to the moon. Delivering the first brings an answer from an exiled celestial who has been waiting for a human reply.", "description_zh": "乡间信使接到寄往月宫的信。第一封送达后，被放逐的仙人终于等到了人间的回音。", "character_brief": "Qiao, 24, female, dark hair in a simple bun with silver pin, blue-gray eyes, pale blue hanfu"}, {"id": "story-006", "title": "A Scholarship from the Demon King", "title_zh": "来自魔王的奖学金", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "669K", "tag": "Fantasy", "replaces": "6a923ed2eba49d6c2184afdf", "image": "/assets/originals/story-006.webp", "description": "An anonymous patron pays your tuition in exchange for monthly reports. The patron is the demon king, and your first assignment is to keep the future hero alive.", "description_zh": "匿名资助者支付学费，条件是定期汇报。对方竟是魔王，而你的任务是保护未来的勇者。", "character_brief": "Vesper, 25, male, silver hair, red eyes, burgundy formal coat and subtle horn-shaped brooch"}, {"id": "story-020", "title": "A Healer for the Enemy", "title_zh": "敌军的治疗师", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "664.6K", "tag": "Fantasy", "replaces": "69f34cc98c9917774c8bd74e", "image": "/assets/originals/story-020.webp", "description": "Captured beyond the front line, you are ordered to save an enemy commander. His wounds carry the signature of your own kingdom's forbidden healing magic.", "description_zh": "被俘后，你奉命救治敌军统帅，却发现伤口来自本国严禁使用的治疗术。", "character_brief": "Evan, 28, male, ash-blond hair, green eyes, cream healer robes with teal sash"}, {"id": "story-017", "title": "The Last Inn Before the Abyss", "title_zh": "深渊之前的最后一家旅店", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "662.5K", "tag": "Fantasy", "replaces": "69f3e25b3734ae348a9ec88a", "image": "/assets/originals/story-017.webp", "description": "You inherit an inn at the edge of a bottomless rift. Every guest is fleeing a different ending, and tonight one room has been booked by the abyss itself.", "description_zh": "你继承深渊边的旅店。住客都在逃避各自的结局，而今晚深渊也订了一间房。", "character_brief": "Mae, 29, female, wavy dark red hair, amber eyes, cream blouse and deep green innkeeper vest"}, {"id": "story-044", "title": "The Museum of Unlived Lives", "title_zh": "未曾活过的人生博物馆", "author": "StoryDate Studio", "genre": "Horror", "type": "story", "original": true, "plays": "", "sortPlays": "606.4K", "tag": "Horror", "replaces": "6a9f663279b675aa7c3d0c81", "image": "/assets/originals/story-044.webp", "description": "A private museum displays the lives its visitors almost chose. Your exhibit is empty, and the curator insists someone else is still living every future you abandoned.", "description_zh": "博物馆陈列访客未选择的人生。你的展柜却是空的，馆长说有人仍在替你活着那些未来。", "character_brief": "Ivo, 29, male, dark wavy hair, violet-gray eyes, tailored cream suit and dark shirt"}, {"id": "sg-007", "title": "The Tale of Diaochan", "title_zh": "貂蝉传", "author": "StoryDate Studio", "genre": "History", "type": "story", "original": true, "plays": "", "sortPlays": "603K", "tag": "History", "replaces": "6a9aea5361615e63e584428b", "image": "/assets/originals/sg-007.webp", "description": "She was given a role in a plot far bigger than herself. Walk the palace corridors with her and see where a chosen path turns into her own.", "description_zh": "她被安排进一场远比自己更大的棋局。与她走过宫廷长廊，看被安排的路从哪里变成她自己的选择。", "character_brief": "Diaochan, early 20s, female, long black hair, pale silk dress, quiet and watchful"}, {"id": "story-034", "title": "After the Encore", "title_zh": "返场之后", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "561.6K", "tag": "Romance", "replaces": "69f3b9b2d82bf6478de63cd2", "image": "/assets/originals/story-034.webp", "description": "A sound engineer helps a singer rebuild her career after their band's breakup. One unfinished song draws them back together, but neither agrees on how it should end.", "description_zh": "乐队解散后，录音师帮主唱重新出发。一首未完成的歌让两人重逢，却没人愿意先写下结尾。", "character_brief": "Rae, 28, female, short silver-lavender hair, brown eyes, black stage jacket"}, {"id": "story-018", "title": "I Deliver Letters to Dragons", "title_zh": "我替巨龙送信", "author": "StoryDate Studio", "genre": "Fantasy", "type": "story", "original": true, "plays": "", "sortPlays": "546.4K", "tag": "Fantasy", "replaces": "69f3b035d82bf6478de63b43", "image": "/assets/originals/story-018.webp", "description": "The mountain post hires you for a route no rider survives. Your first letter is addressed to a dragon thought dead, and its reply could restart a forgotten war.", "description_zh": "你接手无人敢走的巨龙邮路。第一封信寄给一条传说中已死的龙，回信可能重启旧日战争。", "character_brief": "Tessa, 24, female, short auburn hair, amber eyes, teal flight jacket and leather mail satchel"}, {"id": "story-029", "title": "The Girl on the Other Balcony", "title_zh": "对面阳台的女孩", "author": "StoryDate Studio", "genre": "Romance", "type": "story", "original": true, "plays": "", "sortPlays": "521.1K", "tag": "Romance", "replaces": "6a322cc5ad59efa80e53229e", "image": "/assets/originals/story-029.webp", "description": "You exchange plant-care notes with the woman across the courtyard. When demolition notices arrive, finding a way to meet becomes a race to save the place that connected you.", "description_zh": "你与对面阳台的女孩交换养花便笺。拆迁通知出现后，见面成了挽救共同生活角落的开始。", "character_brief": "Leah, 26, female, shoulder-length black hair, hazel eyes, loose pale-yellow linen shirt"}];
